import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r'''
#include <cuda_fp16.h>
#include <cuda_runtime.h>
#include <math_constants.h>

template <int BLOCK_SIZE>
__global__ void groupnorm_sum_kernel(const __half* __restrict__ x,
                                     float* __restrict__ mean,
                                     float* __restrict__ var,
                                     int N, int C, int H, int W, int G) {
    // one block per (n, g)
    const int n = blockIdx.x;
    const int g = blockIdx.y;
    const int Cpg = C / G;                 // channels per group
    const int spatial = H * W;
    const int group_elems = Cpg * spatial; // elements per group

    // stride loop over the elements of this (n,g) group
    float sum = 0.0f;
    float sumsq = 0.0f;
    for (int idx = threadIdx.x; idx < group_elems; idx += BLOCK_SIZE) {
        int c_in_group = idx / spatial;          // 0 .. Cpg-1
        int s = idx % spatial;                   // 0 .. H*W-1
        int c = g * Cpg + c_in_group;            // absolute channel
        int h = s / W;
        int w = s % W;
        int offset = ((n * C + c) * H + h) * W + w;
        __half val_h = x[offset];
        float val = __half2float(val_h);
        sum   += val;
        sumsq += val * val;
    }

    // reduction within block
    __shared__ float sh_sum[BLOCK_SIZE];
    __shared__ float sh_sumsq[BLOCK_SIZE];
    sh_sum[threadIdx.x]   = sum;
    sh_sumsq[threadIdx.x] = sumsq;
    __syncthreads();

    // tree reduction
    for (int stride = BLOCK_SIZE / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            sh_sum[threadIdx.x]   += sh_sum[threadIdx.x + stride];
            sh_sumsq[threadIdx.x] += sh_sumsq[threadIdx.x + stride];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        float mean_val = sh_sum[0] / static_cast<float>(group_elems);
        float var_val  = sh_sumsq[0] / static_cast<float>(group_elems) - mean_val * mean_val;
        mean[n * G + g] = mean_val;
        var[n * G + g]  = var_val;
    }
}

__global__ void groupnorm_norm_kernel(const __half* __restrict__ x,
                                      const float* __restrict__ mean,
                                      const float* __restrict__ var,
                                      const __half* __restrict__ weight,
                                      const __half* __restrict__ bias,
                                      __half* __restrict__ y,
                                      int N, int C, int H, int W, int G,
                                      float eps) {
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    const int total = N * C * H * W;
    if (idx >= total) return;

    int w = idx % W;
    int tmp = idx / W;
    int h = tmp % H;
    tmp = tmp / H;
    int c = tmp % C;
    int n = tmp / C;

    int g = c / (C / G);
    float m = mean[n * G + g];
    float v = var[n * G + g];
    float inv_std = rsqrtf(v + eps);

    float val = __half2float(x[idx]);
    float norm = (val - m) * inv_std;

    float wgt = __half2float(weight[c]);
    float b   = __half2float(bias[c]);

    float out = norm * wgt + b;
    y[idx] = __float2half(out);
}
'''

module = load_inline(name='groupnorm_cuda',
                     cpp_sources='',
                     cuda_sources=cuda_source,
                     functions=['groupnorm_sum_kernel<256>', 'groupnorm_norm_kernel'],
                     verbose=False)

class GroupNormFunction(torch.autograd.Function):
