    def forward(ctx, x, weight, bias, num_groups, eps):
        assert x.is_cuda and x.dtype == torch.float16
        N, C, H, W = x.shape
        G = num_groups
        assert C % G == 0, "num_channels must be divisible by num_groups"

        # allocate temporary buffers for mean/var (float32)
        mean = torch.empty(N * G, device=x.device, dtype=torch.float32)
        var  = torch.empty(N * G, device=x.device, dtype=torch.float32)

        # launch sum kernel (one block per (n,g))
        block = 256
        grid = (N, G)
        module.groupnorm_sum_kernel[grid, block, 0, torch.cuda.current_stream().cuda_stream](
            x,
            mean,
            var,
            N, C, H, W, G
        )

        # launch normalization kernel
        total = N * C * H * W
        block2 = 256
        grid2 = ( (total + block2 - 1) // block2, )
        module.groupnorm_norm_kernel[grid2, block2, 0, torch.cuda.current_stream().cuda_stream](
            x,
            mean,
            var,
            weight,
            bias,
            torch.empty_like(x),
            N, C, H, W, G,
            float(eps)
        )
        y = torch.empty_like(x)
        module.groupnorm_norm_kernel[grid2, block2, 0, torch.cuda.current_stream().cuda_stream](
            x,
            mean,
            var,
            weight,
            bias,
            y,
            N, C, H, W, G,
            float(eps)
        )
        return y

