    """
    Drop‑in replacement for the reference Model using a custom CUDA GroupNorm kernel.
    """
    def __init__(self, num_features: int, num_groups: int, eps: float = 1e-5):
        super().__init__()
        self.num_groups = num_groups
        self.eps = eps
        # affine parameters in fp16 on GPU
        self.weight = nn.Parameter(torch.ones(num_features,
                                              dtype=torch.float16,
                                              device='cuda'))
        self.bias = nn.Parameter(torch.zeros(num_features,
                                             dtype=torch.float16,
                                             device='cuda'))

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if x.dtype != torch.float16:
            x = x.to(torch.float16)
        return GroupNormFunction.apply(x, self.weight, self.bias,
                                       self.num_groups, self.eps)

