    batch_size = 112
    features = 64
    num_groups = 8
    dim1 = 512
    dim2 = 512

    model = ModelNew(num_features=features, num_groups=num_groups).cuda()
    x = torch.rand(batch_size, features, dim1, dim2, device='cuda', dtype=torch.float16)
